/**
 * Lossless pre-decoded Red-to-Blue wetness percentage grids derived directly
 * from the bundled NASA NISAR PNG overlays in `nisar_data/`.
 * Enables exact native-pixel moisture inspection across file://, HTTP(S), and
 * offline sessions without canvas cross-origin restrictions.
 */
(function (globalScope) {
  'use strict';

  const RASTER_ENTRIES = {
    "nisar_data/santiago_del_estero_capital_gcov_blue.png": {
      w: 393,
      h: 289,
      bounds: {"west": -64.4987, "south": -27.9933, "east": -63.8676, "north": -27.5779},
      b64: ''
    },
    "nisar_data/mozambique_chokwe_macia_floods_2026_before_blue.png": {
      w: 322,
      h: 488,
      bounds: {"west": 32.8, "south": -25.15, "east": 33.35, "north": -24.4},
      b64: ''
    },
    "nisar_data/mozambique_chokwe_macia_floods_2026_after_blue.png": {
      w: 322,
      h: 488,
      bounds: {"west": 32.8, "south": -25.15, "east": 33.35, "north": -24.4},
      b64: ''
    },
    "nisar_data/nepal_china_gyirong_port_floods_2026_track_a_ascending_before_blue.png": {
      w: 156,
      h: 141,
      bounds: {"west": 85.3, "south": 28.14, "east": 85.56, "north": 28.34},
      b64: ''
    },
    "nisar_data/nepal_china_gyirong_port_floods_2026_track_a_ascending_after_blue.png": {
      w: 156,
      h: 141,
      bounds: {"west": 85.3, "south": 28.14, "east": 85.56, "north": 28.34},
      b64: ''
    },
    "nisar_data/nepal_china_gyirong_port_floods_2026_track_b_descending_before_blue.png": {
      w: 299,
      h: 374,
      bounds: {"west": 85.1, "south": 27.85, "east": 85.6, "north": 28.38},
      b64: ''
    },
    "nisar_data/nepal_china_gyirong_port_floods_2026_track_b_descending_after_blue.png": {
      w: 316,
      h: 395,
      bounds: {"west": 85.1, "south": 27.85, "east": 85.6, "north": 28.38},
      b64: ''
    }
  };

  const B64_LOOKUP = (() => {
    const table = new Int16Array(256).fill(-1);
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    for (let i = 0; i < chars.length; i++) table[chars.charCodeAt(i)] = i;
    return table;
  })();

  function decodeBase64ToBytes(b64) {
    if (typeof atob === 'function') {
      const bin = atob(b64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) {
        bytes[i] = bin.charCodeAt(i);
      }
      return bytes;
    }
    if (typeof Buffer !== 'undefined') {
      const buf = Buffer.from(b64, 'base64');
      return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
    }
    const len = b64.length;
    let pad = 0;
    if (len >= 1 && b64[len - 1] === '=') pad++;
    if (len >= 2 && b64[len - 2] === '=') pad++;
    const out = new Uint8Array(((len * 3) >> 2) - pad);
    let j = 0;
    for (let i = 0; i < len; i += 4) {
      const a = B64_LOOKUP[b64.charCodeAt(i)];
      const b = B64_LOOKUP[b64.charCodeAt(i + 1)];
      const c = b64[i + 2] === '=' ? 0 : B64_LOOKUP[b64.charCodeAt(i + 2)];
      const d = b64[i + 3] === '=' ? 0 : B64_LOOKUP[b64.charCodeAt(i + 3)];
      const n = (a << 18) | (b << 12) | (c << 6) | d;
      out[j++] = (n >> 16) & 255;
      if (b64[i + 2] !== '=') out[j++] = (n >> 8) & 255;
      if (b64[i + 3] !== '=') out[j++] = n & 255;
    }
    return out;
  }

  function decodeTenths(entry) {
    if (!entry) return null;
    if (entry._tenths) return entry._tenths;
    const bytes = decodeBase64ToBytes(entry.b64);
    const count = bytes.byteLength >>> 1;
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const arr = new Uint16Array(count);
    for (let i = 0; i < count; i++) {
      arr[i] = view.getUint16(i * 2, true);
    }
    entry._tenths = arr;
    return arr;
  }

  function normalizePath(imagePath) {
    if (!imagePath) return '';
    return String(imagePath).replace(/^\.?\//, '');
  }

  function hasRaster(imagePath) {
    return Boolean(RASTER_ENTRIES[normalizePath(imagePath)]);
  }

  function getRasterRecord(imagePath, overlayBounds) {
    const entry = RASTER_ENTRIES[normalizePath(imagePath)];
    if (!entry) return null;
    const tenths = decodeTenths(entry);
    return {
      ready: true,
      width: entry.w,
      height: entry.h,
      tenths: tenths,
      bounds: overlayBounds || entry.bounds
    };
  }

  globalScope.LambdaXRasterGrids = {
    hasRaster: hasRaster,
    getRasterRecord: getRasterRecord,
    listPaths: function () {
      return Object.keys(RASTER_ENTRIES);
    }
  };
})(typeof window !== 'undefined' ? window : globalThis);
